NavierStokes.GraphCalculus.along.source:
/-- Differentiation along a vector field, defined by the genuine derivative. -/
def along (V : Lift → Lift) (F : Lift → ℝ) (p : Lift) : ℝ :=
  fderiv ℝ F p (V p)

NavierStokes.OscillatoryCurl.phaseNormal.source:
/-- Physical spatial phase normal, with time held fixed. -/
def phaseNormal (Φ : PressureField) : VelocityField :=
  fun z => gradientLinear (fderiv ℝ (fun y : Space => Φ (z.1, y)) z.2)
